import os, json, re
from collections import Counter

# Load all grids from session  
d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

# Verify test input shape and content
test_in = G.get('Test input')
print(f"Test input shape: {len(test_in)}x{len(test_in[0])}")
print(f"Total cells: {len(test_in) * len(test_in[0])}")

# Count cells precisely
counts = {}
for row in test_in:
    for val in row:
        counts[val] = counts.get(val, 0) + 1

print(f"\nCell counts: {counts}")

# Verify by comparing loaded JSON file
with open('/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-2/play/users/u015/system/state/workspace/test_input.json') as f:
    j_test = json.load(f)

j_counts = Counter()
for row in j_test:
    for val in row:
        j_counts[val] += 1

print(f"\nJSON file counts: {dict(j_counts)}")

# Now let's check demo 2 more carefully
demo2_in = G.get('Demo pair 2 input')
demo2_out = G.get('Demo pair 2 output')

demo2_counts_in = Counter()
demo2_counts_out = Counter()
for row in demo2_in:
    for val in row:
        demo2_counts_in[val] += 1
for row in demo2_out:
    for val in row:
        demo2_counts_out[val] += 1

print(f"\n\nDemo 2 input counts: {dict(demo2_counts_in)}")
print(f"Demo 2 output counts: {dict(demo2_counts_out)}")

# What if there are MORE than 2 colors?
all_vals_in = set()
all_vals_out = set()
for row in demo2_in:
    for val in row:
        all_vals_in.add(val)
for row in demo2_out:
    for val in row:
        all_vals_out.add(val)

print(f"\nDemo 2 unique values in: {sorted(all_vals_in)}")
print(f"Demo 2 unique values out: {sorted(all_vals_out)}")

