import os, json, re

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

# Parse JSONL and find messages related to task submission/response
print("Looking for task responses...")

for i, line in enumerate(t.split('\n')):
    if not line.strip():
        continue
    try:
        msg = json.loads(line)
        if 'message' in msg:
            content = msg.get('message', {}).get('content', '')
            ts = msg.get('message', {}).get('timestamp', '')
            if ts >= '2026-10-29T16:35:':
                # Print messages from after our submission time
                print(f"Time {ts[:26]}: {content[:80]}")
    except:
        pass

